<?php
declare(strict_types=1);
return static function(PDO $pdo):void{
 $pdo->exec("CREATE TABLE IF NOT EXISTS listening_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,classroom_id BIGINT UNSIGNED NOT NULL,member_id BIGINT UNSIGNED NOT NULL,lesson_plan_id BIGINT UNSIGNED NOT NULL,level ENUM('basic','intermediate','advanced') NOT NULL,snapshot_json JSON NOT NULL,current_position SMALLINT UNSIGNED NOT NULL DEFAULT 0,score SMALLINT UNSIGNED NOT NULL DEFAULT 0,replay_count TINYINT UNSIGNED NOT NULL DEFAULT 0,question_started_at DATETIME NULL,status ENUM('active','completed','abandoned') NOT NULL DEFAULT 'active',started_at DATETIME NOT NULL,completed_at DATETIME NULL,KEY idx_listening_resume(member_id,classroom_id,level,status),CONSTRAINT fk_ls_classroom FOREIGN KEY(classroom_id) REFERENCES classrooms(id) ON DELETE CASCADE,CONSTRAINT fk_ls_member FOREIGN KEY(member_id) REFERENCES classroom_members(id) ON DELETE CASCADE,CONSTRAINT fk_ls_plan FOREIGN KEY(lesson_plan_id) REFERENCES classroom_lesson_plans(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE IF NOT EXISTS listening_session_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listening_session_id BIGINT UNSIGNED NOT NULL,activity_id BIGINT UNSIGNED NOT NULL,selected_answer VARCHAR(32) NULL,result ENUM('correct','incorrect','timed_out') NOT NULL,response_ms INT UNSIGNED NOT NULL DEFAULT 0,score SMALLINT UNSIGNED NOT NULL DEFAULT 0,replay_count TINYINT UNSIGNED NOT NULL DEFAULT 0,answered_at DATETIME NOT NULL,UNIQUE KEY uq_listening_answer(listening_session_id,activity_id),KEY idx_listening_history(activity_id,listening_session_id),CONSTRAINT fk_lsa_session FOREIGN KEY(listening_session_id) REFERENCES listening_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_lsa_activity FOREIGN KEY(activity_id) REFERENCES learning_activities(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
